style.css:
/* Studio Silence — BandLab */

:root {
  /* swap these colors if you want */
  --my-bg: #f7f7f5;
  --my-surface: #ffffff;
  --my-text: #242424;
  --my-muted: #888985;
  --my-border: #e9e9e5;
  --my-accent: #777b70;
}

/* clean page background */
body {
  background: var(--my-bg) !important;
  color: var(--my-text) !important;
  font-family: Inter, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif !important;
}

/* subtle typography */
h1, h2, h3, h4 {
  color: var(--my-text) !important;
  letter-spacing: -0.035em !important;
}

/* softer links */
a {
  transition: color 0.2s ease !important;
}

/* gentle image corners */
img {
  border-radius: 8px;
}

/* cleaner scrollbars */
::-webkit-scrollbar {
  width: 8px;
}

::-webkit-scrollbar-thumb {
  background: #d5d5cf !important;
  border-radius: 20px !important;
}

/* subtle selection */
::selection {
  background: #deded6 !important;
  color: #242424 !important;
}
